export default function Product(props) {
  return (
    <span className={`productTile product_${props.id}`}>
      <h2>{props.name}</h2>
      <p>Price: ₹{props.price}</p>
      {props.img_src && <img src={props.img_src} alt={props.name} width={props.dimensions.width} height={props.dimensions.height} />}
      <p>{props.description}</p>
    </span>
  );
}
